<script setup>
import {computed,ref} from 'vue';
import {Head,Link,useForm} from '@inertiajs/vue3';
import AdminPagination from '@/Components/Admin/AdminPagination.vue';
import AdminLayout from '@/Layouts/AdminLayout.vue';
import UserAvatar from '@/Components/Account/UserAvatar.vue';
import ListingImage from '@/Components/Marketplace/ListingImage.vue';
import AdminListingPreview from '@/Components/Admin/AdminListingPreview.vue';
import RoleStatusBadge from '@/Components/Admin/RoleStatusBadge.vue';
import AccountSettingsDrawer from '@/Components/Admin/AccountSettingsDrawer.vue';
const props=defineProps({owner:Object,results:Object,service:String,counts:Object,restrictionReasons:Object,deletionReasons:Object,restrictionHistory:Array});
const settingsOpen=ref(false);
const accountState=computed(()=>props.owner.deletion_scheduled_for?{key:'deleting',label:'Scheduled for deletion'}:props.owner.restricted?{key:'off',label:props.owner.restriction_type==='locked'?'Locked':'Disabled'}:{key:'active',label:'Active'});
const selected=ref(null),labels={spaces:'Properties',haul:'Vehicles',raketeer:'Rakets & services'};
const plusForm=useForm({aadi_plus_until:props.owner.aadi_plus_until?.slice(0,10)||''});
function updatePlus(){plusForm.transform(data=>({...data,aadi_plus_until:data.aadi_plus_until||null})).patch(`/admin/users/${props.owner.id}/aadi-plus`,{preserveScroll:true});}
</script>
<template><Head :title="`${owner.name} — Admin listings`"/><AdminLayout><template #header><h1 class="inventory-title">User listings</h1></template><Link href="/admin/users" class="inventory-back">← All users</Link><header class="inventory-owner"><UserAvatar :user="owner" class="owner-avatar"/><div class="owner-info"><h2>{{ owner.name }} <span class="account-state" :data-state="accountState.key">{{ accountState.label }}</span></h2><p>{{ owner.email }}</p><div class="owner-roles"><RoleStatusBadge service="spaces" :status="owner.landlord_status||'none'"/><RoleStatusBadge service="haul" :status="owner.vehicle_owner_status||'none'"/><RoleStatusBadge service="raketeer" :status="owner.service_provider_status||'none'"/></div></div><div class="owner-actions"><button type="button" class="owner-profile" aria-haspopup="dialog" @click="settingsOpen=true">⚙ Settings</button><Link :href="`/providers/${owner.id}`" class="owner-profile">Public profile ↗</Link></div></header><AccountSettingsDrawer :open="settingsOpen" :owner="owner" :restriction-reasons="restrictionReasons" :deletion-reasons="deletionReasons" :history="restrictionHistory" @close="settingsOpen=false"><template #plus><section class="plus-controls" aria-labelledby="plus-title"><div><h2 id="plus-title">Aadi Plus</h2><p>{{ owner.aadiPlus ? `Active until ${owner.aadi_plus_until?.slice(0,10)}` : 'No active entitlement' }}. This admin-managed entitlement has no checkout or billing.</p></div><form @submit.prevent="updatePlus"><label>Entitlement end date<input v-model="plusForm.aadi_plus_until" type="date" :min="new Date().toISOString().slice(0,10)" :disabled="plusForm.processing"/></label><button type="submit" :disabled="plusForm.processing">{{ plusForm.processing ? 'Saving…' : 'Update entitlement' }}</button><button v-if="owner.aadiPlus || plusForm.aadi_plus_until" type="button" class="plus-revoke" :disabled="plusForm.processing" @click="plusForm.aadi_plus_until='';updatePlus()">Remove</button></form><p v-if="plusForm.errors.aadi_plus_until" role="alert" class="plus-error">{{ plusForm.errors.aadi_plus_until }}</p></section></template></AccountSettingsDrawer><nav class="inventory-tabs" aria-label="User listing categories"><Link v-for="(label,key) in labels" :key="key" :href="`/admin/users/${owner.id}/listings?service=${key}`" :aria-current="service===key?'page':undefined">{{ label }} <span>{{ counts[key] }}</span></Link></nav><p class="inventory-hint">All current records, including drafts and inactive listings. Select a listing to inspect it.</p><div v-if="!results.data.length" class="inventory-empty">This user has no {{ labels[service].toLowerCase() }}.</div><div class="inventory-grid"><button v-for="item in results.data" :key="item.id" type="button" class="inventory-card" aria-haspopup="dialog" @click="selected=item"><div class="inventory-photo"><ListingImage :src="item.photos?.[0]" :alt="item.title" :service="service" :type="item.type"/></div><div class="inventory-card-body"><span class="inventory-status">{{ item.sourceStatus }}</span><h3>{{ item.title }}</h3><p>{{ new Intl.NumberFormat('en-PH',{style:'currency',currency:item.currency}).format(item.price) }} / {{ item.priceUnit }}</p><small>{{ item.photos?.length || 0 }} photos · {{ item.type }}</small><span class="inventory-inspect">Inspect listing →</span></div></button></div><AdminPagination :paginator="results" :sizes="[12,24,48]" label="User listing pages"/><AdminListingPreview v-if="selected" :item="selected" :owner="owner" @close="selected=null"/></AdminLayout></template>
<style scoped>
.owner-actions{display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-end}button.owner-profile{cursor:pointer}.account-state{display:inline-block;vertical-align:middle;margin-left:6px;padding:3px 9px;border-radius:999px;font-size:11px;font-weight:700;background:#e3f6f4;color:#12675f}.account-state[data-state=off]{background:#fde8e8;color:#9b1c1c}.account-state[data-state=deleting]{background:#fff1d6;color:#8a4b00}.account-state::before{content:'';display:inline-block;width:6px;height:6px;margin-right:6px;border-radius:50%;background:currentColor;vertical-align:middle}@media(max-width:600px){.owner-actions{grid-column:1 / -1;justify-content:stretch}.owner-actions .owner-profile{flex:1;justify-content:center}}
.plus-controls{display:flex;flex-direction:column;align-items:stretch;gap:14px}.plus-controls h2{margin:0;font-size:16px;font-weight:700}.plus-controls p{margin:6px 0 0;color:#637b76;font-size:12px;line-height:1.5}.plus-controls .plus-error{flex-basis:100%;margin:0;color:#9b1c1c}.plus-controls form{display:flex;align-items:end;gap:8px;flex-wrap:wrap}.plus-controls label{display:grid;gap:5px;font-size:11px;color:#637b76}.plus-controls input{min-height:38px;border:1px solid #cbded8;border-radius:7px;padding:6px 9px;color:#183e3b}.plus-controls button{min-height:38px;padding:0 12px;border:1px solid #137671;border-radius:7px;background:#137671;color:white;font-size:12px;font-weight:700}.plus-controls .plus-revoke{background:white;color:#7f1d1d;border-color:#e5b7b7}@media(max-width:700px){.plus-controls{align-items:stretch;flex-direction:column}.plus-controls form{align-items:stretch}.plus-controls label{flex:1}}
.owner-roles{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}.inventory-title{font-size:24px;font-weight:700}.inventory-back{font-size:13px;color:#137671}.inventory-owner{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:start;column-gap:18px;row-gap:12px;margin:24px 0;padding:20px;background:#fff;border:1px solid #dce7e4;border-radius:14px}.inventory-owner :deep(.owner-avatar){width:72px;height:72px;font-size:24px}.owner-info{min-width:0}.inventory-owner h2{font-size:22px;line-height:1.25;font-weight:700;overflow-wrap:anywhere;margin:0}.inventory-owner p{font-size:13px;color:#637b76;overflow-wrap:anywhere;margin:4px 0 0}.owner-profile{align-self:start;display:inline-flex;align-items:center;min-height:40px;padding:0 14px;border:1px solid #cbded8;border-radius:10px;background:#fff;font-size:13px;font-weight:700;color:#12675f;white-space:nowrap}.owner-profile:hover{background:#e3f6f4}.owner-profile:focus-visible{outline:2px solid #137671;outline-offset:3px}.inventory-tabs{display:flex;gap:10px;flex-wrap:wrap}.inventory-tabs a{padding:10px 14px;border:1px solid #c9dcd6;background:white;border-radius:8px;font-size:13px;font-weight:600}.inventory-tabs a[aria-current]{background:#137671;color:white;border-color:#137671}.inventory-tabs span{margin-left:8px;opacity:.8}.inventory-hint{font-size:12px;color:#637b76;margin:16px 0 24px}.inventory-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.inventory-card{border:1px solid #dce7e4;background:white;border-radius:12px;overflow:hidden;text-align:left;cursor:pointer}.inventory-photo{height:170px}.inventory-card-body{padding:18px}.inventory-status{font-size:10px;text-transform:uppercase;letter-spacing:.05em;background:#edf4f1;color:#12675f;padding:4px 7px;border-radius:5px;font-weight:700}.inventory-card h3{font-size:17px;font-weight:700;margin:12px 0 8px;overflow-wrap:anywhere}.inventory-card p{font-size:13px}.inventory-card small{display:block;color:#637b76;font-size:11px;margin-top:8px}.inventory-inspect{display:block;color:#137671;font-size:12px;font-weight:700;margin-top:20px}.inventory-empty{padding:40px;border:1px dashed #bacfc8;border-radius:12px;text-align:center}.inventory-pagination{display:flex;justify-content:center;gap:20px;margin-top:24px}.inventory-card:focus-visible,.inventory-tabs a:focus-visible{outline:2px solid #137671;outline-offset:3px}@media(max-width:1200px){.inventory-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.inventory-grid{grid-template-columns:1fr}.inventory-owner{grid-template-columns:auto minmax(0,1fr)}.inventory-owner :deep(.owner-avatar){width:56px;height:56px;font-size:19px}.owner-profile{grid-column:1 / -1;justify-content:center}}
</style>
